'use strict';

/**
 * Merge overlapping or touching [start, end] integer ranges.
 *
 * @param {Array<[number, number]>} ranges - Unsorted ranges where start <= end.
 * @returns {Array<[number, number]>} New array of merged, non-overlapping ranges sorted by start.
 */
function mergeOverlappingRanges(ranges) {
  if (!Array.isArray(ranges) || ranges.length === 0) {
    return [];
  }

  const sorted = ranges
    .map(([start, end]) => [start, end])
    .sort((a, b) => a[0] - b[0] || a[1] - b[1]);

  const merged = [sorted[0]];
  for (let i = 1; i < sorted.length; i++) {
    const last = merged[merged.length - 1];
    const [start, end] = sorted[i];
    if (start <= last[1]) {
      last[1] = Math.max(last[1], end);
    } else {
      merged.push([start, end]);
    }
  }

  return merged;
}

module.exports = { mergeOverlappingRanges };

